# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">OSMANLI\'NIN BİZANS VE BALKANLAR\'DAKİ ASKERÎ MÜCADELELERİ (TAR.10.2.2)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">BİZANS İLE MÜCADELE VE RUMELİ\'YE GEÇİŞ</text>\n  <text x="32" y="88" font-size="10.5" fill="#1e3a8a">• Koyunhisar / Bafeus (1302): Osman Bey\'in Bizans\'a karşı</text>\n  <text x="32" y="104" font-size="10.5" font-weight="bold" fill="#1d4ed8">  kazandığı ilk zafer; beyliğin kuruluşu (Halil İnalcık).</text>\n  <text x="32" y="124" font-size="10.5" fill="#1e3a8a">• Bursa\'nın Fethi (1326): Orhan Bey döneminde başkent oldu.</text>\n  <text x="32" y="144" font-size="10.5" fill="#1e3a8a">• Palekanon / Maltepe (1329): İznik (1331) ve İzmit (1337)</text>\n  <text x="32" y="160" font-size="10.5" fill="#1e3a8a">  fethedilerek Kocaeli Yarımadası\'nda hâkimiyet kuruldu.</text>\n  <text x="32" y="180" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Çimpe Kalesi (1353): Süleyman Paşa ile Rumeli\'de ilk üs!</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">HAÇLI İTTİFAKLARIYLA MEYDAN MUHAREBELERİ</text>\n  <text x="372" y="88" font-size="10.5" fill="#14532d">• Sazlıdere (1361) &amp; Edirne\'nin Fethi: Balkan fetih merkezi.</text>\n  <text x="372" y="108" font-size="10.5" fill="#14532d">• Sırpsındığı (1364): Haçlılarla yapılan ilk savaş; zafer!</text>\n  <text x="372" y="128" font-size="10.5" fill="#14532d">• Çirmen (1371): Makedonya kapıları Osmanlı\'ya açıldı.</text>\n  <text x="372" y="148" font-size="10.5" fill="#14532d">• I. Kosova (1389): Balkan Haçlı ordusu yenildi; I. Murad</text>\n  <text x="372" y="164" font-size="10.5" fill="#14532d">  savaş meydanında şehit düştü, ilk kez top kullanıldı.</text>\n  <text x="372" y="184" font-size="10.5" font-weight="bold" fill="#15803d">• Niğbolu (1396): Yıldırım Bayezid Avrupa Haçlılarını yendi.</text>\n  <text x="372" y="202" font-size="10.5" fill="#14532d">• Varna (1444) &amp; II. Kosova (1448): Balkanlar kesin Türk yurdu!</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Osmanlı Devleti; gaza ruhu, istimâlet (hoşgörü) ve iskân politikasıyla Balkanlar\'da kalıcı hâkimiyet kurmuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">ANADOLU TÜRK SİYASİ BİRLİĞİNİ SAĞLAMA POLİTİKASI (BARIŞÇIL VE ASKERÎ)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. BARIŞÇIL VE DİPLOMATİK YÖNTEMLER</text>\n  <text x="32" y="88" font-size="10.5" fill="#78350f">• Karesioğulları (1345): Orhan Bey döneminde iç karışıklıktan</text>\n  <text x="32" y="106" font-size="10.5" font-weight="bold" fill="#92400e">  yararlanılarak alınan İLK beylik (Donanma ve Rumeli yolu!).</text>\n  <text x="32" y="128" font-size="10.5" fill="#78350f">• Germiyanoğulları: I. Murad döneminde Şehzade Bayezid ile</text>\n  <text x="32" y="146" font-size="10.5" fill="#78350f">  Devlet Şah Hatun\'un evliliğiyle Kütahya, Simav, Tavşanlı</text>\n  <text x="32" y="162" font-size="10.5" font-weight="bold" fill="#92400e">  «çeyiz yoluyla» Osmanlı\'ya katıldı.</text>\n  <text x="32" y="184" font-size="10.5" fill="#78350f">• Hamitoğulları: Akşehir, Beyşehir ve Isparta «80 bin altın</text>\n  <text x="32" y="200" font-size="10.5" font-weight="bold" fill="#92400e">  karşılığında satın alınarak» Osmanlı topraklarına katıldı.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">2. ASKERÎ MÜCADELELER (YILDIRIM BAYEZİD)</text>\n  <text x="372" y="88" font-size="10.5" fill="#581c87">• Karamanoğulları: Kendini Anadolu Selçuklu mirasçısı</text>\n  <text x="372" y="106" font-size="10.5" font-weight="bold" fill="#6b21a8">  gördüğü için Osmanlı\'yı en çok uğraştıran beyliktir</text>\n  <text x="372" y="122" font-size="10.5" fill="#581c87">  (1387 Frenkyazısı ve 1397 Akçay savaşları).</text>\n  <text x="372" y="144" font-size="10.5" fill="#581c87">• Yıldırım Bayezid döneminde Saruhanoğulları, Aydınoğulları,</text>\n  <text x="372" y="162" font-size="10.5" fill="#581c87">  Menteşeoğulları, Candaroğulları ve Kadı Burhaneddin</text>\n  <text x="372" y="180" font-size="10.5" fill="#581c87">  toprakları alınarak Anadolu Türk siyasi birliği ilk kez</text>\n  <text x="372" y="198" font-size="10.5" font-weight="bold" fill="#6b21a8">  büyük ölçüde sağlandı; Anadolu Beylerbeyliği (Kütahya) kuruldu.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Osmanlı Devleti başlangıçta beyliklerle çatışmaktan kaçınmış; önce Bizans yönünde büyüyerek güç toplamıştır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">1402 ANKARA SAVAŞI, FETRET DEVRİ VE YENİDEN KURULUŞ (I. MEHMED)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">ANKARA SAVAŞI (28 TEMMUZ 1402 — ÇUBUK OVASI)</text>\n  <text x="32" y="86" font-size="10.4" fill="#7f1d1d">• Taraflar: Yıldırım Bayezid (Osmanlı) vs. Emir Timur</text>\n  <text x="32" y="106" font-size="10.4" font-weight="bold" fill="#991b1b">• Sebepler:</text>\n  <text x="40" y="122" font-size="10.2" fill="#7f1d1d">- İki Türk hükümdarının cihan hâkimiyeti anlayışı</text>\n  <text x="40" y="138" font-size="10.2" fill="#7f1d1d">- Topraklarını kaybeden Anadolu beylerinin Timur\'a</text>\n  <text x="40" y="154" font-size="10.2" fill="#7f1d1d">  Kara Yusuf ile Ahmed Celâyir\'in Yıldırım\'a sığınması</text>\n  <text x="32" y="174" font-size="10.4" font-weight="bold" fill="#991b1b">• Savaşta Kara Tatarların ve eski beylik askerlerinin</text>\n  <text x="32" y="190" font-size="10.2" fill="#7f1d1d">  saf değiştirmesiyle Osmanlı ordusu mağlup oldu.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">SONUÇLARI VE FETRET DEVRİ (1402-1413)</text>\n  <text x="372" y="86" font-size="10.4" fill="#064e3b">• Anadolu Türk siyasi birliği bozuldu; beylikler yeniden kuruldu.</text>\n  <text x="372" y="106" font-size="10.4" fill="#064e3b">• İstanbul\'un fethi yaklaşık yarım asır gecikti.</text>\n  <text x="372" y="126" font-size="10.4" fill="#064e3b">• Yıldırım\'ın 4 oğlu (Süleyman, İsa, Musa, Mehmed) arasında</text>\n  <text x="372" y="142" font-size="10.4" font-weight="bold" fill="#047857">  11 yıl süren taht mücadeleleri (Fetret Devri) yaşandı.</text>\n  <text x="372" y="162" font-size="10.4" fill="#064e3b">• İstimalet politikası sayesinde Balkanlar\'da toprak kaybı</text>\n  <text x="372" y="178" font-size="10.4" fill="#064e3b">  yaşanmadı! 1413\'te Çelebi Mehmed birliği yeniden sağladı</text>\n  <text x="372" y="196" font-size="10.4" font-weight="bold" fill="#047857">  (Devletin «İkinci Kurucusu» kabul edilir).</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Fetret Devri\'nde Anadolu dağılırken Balkan halklarının Osmanlı\'dan ayrılmaması adalet ve istimâlet politikasının kanıtıdır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
